-- 2026-11-11: six new photo stops plus the Kurashiki morning canal, approved by Nathan.
-- Coordinates from OpenStreetMap (Nominatim/Overpass): Hanegi Park leisure=park, Nihon Minka-en museum,
-- Owakudani natural=valley node 293704434, トンバイ塀 attraction, Fukuyama shinkansen platform way 725394080,
-- Shinjuku Park Tower way 153148303, Kurashiki Nakabashi way 191333739.
insert into koma_shots (trip_id, day_id, title, subtitle, lens, light, at_time, position_md, tech_md, notes_md, priority, status, sort_order, kind, radius_m, look_md, bearing, lat, lng) values
(16, 130, 'Hanegi Park plum festival', 'Some 650 plum trees on a hill in Setagaya, in bloom for the festival.', '85mm / 35mm', 'morning', '09:30',
 'Five minutes from Umegaoka. Walk up into the plum grove on the hill in the middle of the park.', null, null, 'want', 'planned', 23, 'area', 250,
 E'- One branch of blossom against the sky — 85mm wide open, the rest goes soft.\n- Someone photographing the plums with their phone — the photographer is the subject.\n- Festival stalls under the trees — 35mm.\n- Red and white blossom side by side.',
 null, 35.658538, 139.655338),
(16, 130, 'Tokyo from New York Bar', 'Fifty-two floors up over Shinjuku at night.', '35mm', 'night', '21:30',
 'New York Bar on the 52nd floor of the Park Hyatt (Shinjuku Park Tower). Ask for a window seat.',
 'Put the lens hood flat against the glass to kill reflections; a dark sleeve or jacket over the top helps. About 1/15s at f/2, ISO 3200, braced on the glass.', null, 'maybe', 'planned', 24, 'spot', null, null,
 null, 35.685151, 139.690980),
(16, 131, 'Nihon Minka-en', 'An open-air village of thatched farmhouses on a wooded hillside.', '35mm / 85mm', 'morning', '09:30',
 'Walk the loop path up the hillside; most houses can be entered.', null,
 'Hearth fires only burn on some days. Check the museum’s schedule; if one is lit, start there.', 'want', 'planned', 25, 'area', 250,
 E'- A thatched roof against the trees, from below on the path — 35mm.\n- Hearth smoke lit by window light inside a house, if a fire is lit — 35mm, expose for the light.\n- Tools, straw sandals and old wood up close — 85mm.\n- The path between houses with one walker.',
 null, 35.608707, 139.559464),
(16, 132, 'Owakudani', 'Steaming vents, yellow rock and the black eggs, with Fuji behind on a clear day.', '20-70 / 70-200', 'morning', '11:00',
 'From the ropeway station, walk out to the viewing area above the vents.', null,
 'The ropeway sometimes closes for volcanic gas, so treat Fuji from here as a bonus. Fuji is clearest in the morning in winter.', 'want', 'planned', 26, 'area', 350,
 E'- Ropeway cars over the steam — 70-200, the cars small in it.\n- Fuji over the ridge if it shows — 70-200 stacks it big.\n- Someone peeling a black egg in the steam — 35mm.\n- Yellow sulfur rock and vents up close.',
 null, 35.244551, 139.019864),
(16, 137, 'Arita’s Tonbai-bei lanes', 'Back lanes walled with old kiln bricks and broken pottery.', '35mm / 85mm', 'morning', '10:00',
 'Behind the main street in Uchiyama; the lanes wind uphill from the main road.', null, null, 'want', 'planned', 27, 'area', 300,
 E'- A brick wall running uphill with one person on the lane — 35mm.\n- Shards of porcelain set in the clay — 85mm close.\n- Shop windows of blue-and-white porcelain on the main street.\n- A chimney above the roofs.',
 null, 33.191268, 129.899947),
(16, 141, 'Fukuyama Castle with a shinkansen', 'The castle keep rising right behind the bullet-train platforms.', '35mm / 70-200', 'morning', '08:45',
 'On the shinkansen platform at Fukuyama Station, looking northwest at the keep. Wait for a train to pull in so its nose sits under the castle.',
 'About 1/1000s for a train passing; 1/250s is enough for one pulling in.', 'You arrive on the local from Onomichi, so buy a platform ticket (入場券, about ¥150) at the gates to reach the shinkansen level. Do it on arrival, before the 9:00 museum.', 'want', 'planned', 28, 'spot', null, null,
 316, 34.489676, 133.362695),
(16, 136, 'Kurashiki canal before the crowds', 'The canal empty and side-lit, before the shops open.', '35mm / 85mm', 'early morning', '07:45',
 'Nakabashi, the stone bridge in the middle of the canal, then walk the canal path both ways until 8:45.', null,
 'Bread from mugi first at 7:30, back to NAGI by 9:15.', 'must', 'planned', 29, 'spot', null, null,
 null, 34.595825, 133.771763);
update koma_shots set tech_md = 'Dim under the cedars by 4. Expect ISO 3200 or more; keep the shutter at 1/60s or faster.' where id = 103;
